<?php
require_once __DIR__.'/../includes/functions.php';require_login();require_once __DIR__.'/../config/database.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect('careers/index.php');verify_csrf();$roleId=(int)($_POST['job_role_id']??0);$userId=(int)current_user()['user_id'];$st=$pdo->prepare('SELECT saved_role_id FROM saved_job_roles WHERE user_id=? AND job_role_id=?');$st->execute([$userId,$roleId]);if($st->fetchColumn()){$st=$pdo->prepare('DELETE FROM saved_job_roles WHERE user_id=? AND job_role_id=?');$st->execute([$userId,$roleId]);flash('Career role removed from saved items.','info');}else{$st=$pdo->prepare('INSERT IGNORE INTO saved_job_roles (user_id,job_role_id) VALUES (?,?)');$st->execute([$userId,$roleId]);flash('Career role saved.');}redirect('careers/view.php?id='.$roleId);
